window.THREADS["178330"] = {"tid": "178330", "title": "做了个115批量离线助手", "category": "交流", "typeid": "7", "author": "A4魂", "uid": "126605", "date": "2026-11-4 10:27:09", "views": 3144, "replies": 10, "pages_fetched": 1, "post_count": 11, "cover": "assets/images/178330/Wvj8pwJ.png", "all_images": ["assets/images/178330/Wvj8pwJ.png"], "pan": [], "pan_floor": [], "article": {"author": "A4魂", "uid": "126605", "avatar": "", "date": "2026-11-4 10:27:09", "html": "<i class=\"pstatus\"> 本帖最後由 A4魂 於 2026-11-4 12:35 編輯 </i><br />\n<br />\n官方限制一次最多提交115个，脚本会自动处理分批提交<br />\n<br />\n<img src=\"assets/images/178330/Wvj8pwJ.png\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<a id=\"ed2k_F7a\" href=\"ed2k://|file|115批量离线.txt|19676|FB3A55FFD63B24C65A58366F4F4250F7|/\">115批量离线.txt (19.21 KB)</a><br />\n<br />\n或者<br />\n<br />\n<a href=\"https://115cdn.com/s/swl3fis3nkc?password=c536&amp;#\" target=\"_blank\">https://115cdn.com/s/swl3fis3nkc?password=c536&amp;#</a><br />\n115批量离线.txt<br />\n访问码：c536<br />\n<br />\n复制代码添加到你的<a href=\"https://www.tampermonkey.net/\" target=\"_blank\">Tampermonkey</a>中", "images": ["assets/images/178330/Wvj8pwJ.png"]}, "comments": [{"floor": 2, "author": "sasiga", "uid": "140923", "avatar": "", "date": "2026-11-4 12:13:12", "html": "谢谢老哥，不过为啥点了没反应啊", "images": []}, {"floor": 3, "author": "theavenger", "uid": "48686", "avatar": "", "date": "2026-11-4 13:10:06", "html": "不錯，可惜我這種需求量太少。<br />\n一次一般不超過5個", "images": []}, {"floor": 4, "author": "q957571351", "uid": "323204", "avatar": "", "date": "2026-11-4 13:33:20", "html": "我都是复制到记事本上 然后按列排出来 100个100个手动粘进去 不过fc2插件也失效了 没法批量获取磁力&nbsp;&nbsp;很久没有大批量离线了", "images": []}, {"floor": 5, "author": "kenzoiii", "uid": "501506", "avatar": "", "date": "2026-11-4 14:21:03", "html": "技术哥还是得支持的，记得上次那个离线好像也是被官方禁用了？", "images": []}, {"floor": 6, "author": "lubenweiniubi", "uid": "367323", "avatar": "", "date": "2026-11-4 14:31:22", "html": "有没有 115 转成迅雷的技术，穷哥们又不懂这些的。", "images": []}, {"floor": 7, "author": "lx1003", "uid": "350649", "avatar": "", "date": "2026-11-4 14:55:39", "html": "看来程序大佬们也离不开基本需求啊", "images": []}, {"floor": 8, "author": "DarkerZeref", "uid": "400634", "avatar": "", "date": "2026-11-4 15:54:11", "html": "每天都在论坛涨知识啊、。115插件越来越多了", "images": []}, {"floor": 9, "author": "Jraze007", "uid": "460040", "avatar": "", "date": "2026-11-4 17:02:26", "html": "论坛大神越来越多了，老哥有没有想法开个技术贴？", "images": []}, {"floor": 10, "author": "zxbtxwd", "uid": "408804", "avatar": "", "date": "2026-11-4 17:44:12", "html": "很少有这么大量的需要", "images": []}, {"floor": 11, "author": "lovebea", "uid": "99213", "avatar": "", "date": "2026-11-5 02:35:04", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4983023&amp;ptid=178330\" target=\"_blank\"><font color=\"#999999\">q957571351 發表於 2026-11-4 13:33</font></a></font><br />\n我都是复制到记事本上 然后按列排出来 100个100个手动粘进去 不过fc2插件也失效了 没法批量获取磁力&nbsp;&nbsp;很久 ...</blockquote></div><br />\n你下载一个迅雷极速版，每次复制链接的时候，就自动添加在迅雷新建任务里，然后直接全选粘贴到115就可以了", "images": []}]};
