window.THREADS["177834"] = {"tid": "177834", "title": "科技改变生活，浅谈LTX模型的进步与应用", "category": "交流", "typeid": "7", "author": "nidebaba", "uid": "436570", "date": "2026-10-24 00:46:26", "views": 59254, "replies": 89, "pages_fetched": 5, "post_count": 72, "cover": "assets/images/177834/2oFwVcG.jpeg", "all_images": ["assets/images/177834/2oFwVcG.jpeg", "assets/images/177834/1AD7vCY.jpeg", "assets/images/177834/kPxwJO4.jpeg", "assets/images/177834/1NR4bfn.jpeg", "assets/images/177834/SsxVLFS.jpeg", "assets/images/177834/UTBtaBj.jpeg", "assets/images/177834/dgJZFAq.jpeg", "assets/images/177834/migyjGo.jpeg", "assets/images/177834/yQiEWom.jpeg", "assets/images/177834/FA0Kh9Q.jpeg", "assets/images/177834/WHsSs6g.jpeg", "assets/images/177834/qBPPmK2.jpeg", "assets/images/177834/RMjFqh5.jpeg", "assets/images/177834/9PiBi9y.jpeg"], "pan": [], "pan_floor": [], "article": {"author": "nidebaba", "uid": "436570", "avatar": "", "date": "2026-10-24 00:46:26", "html": "今天看到站内有老司機表达自己对LTX破解AV的观点，感觉有必要发个帖子对这项技术进行系统分析了，众所周知视频及图片是由不同色块拼接呈现的，我们所看到的4K8kK高清版本无非就是色块尺寸更小呈现效果更加清晰，而马赛克这一阻碍人类涩涩文明发展的技术则是局部放大色块，使其呈现出局部模糊失真的遮挡效果<br />\n<br />\n有论坛老哥表示LTX破解就是用AI在数据库中找一个类似的B放在视频中而已看久了还会有恐怖谷效应，实际并非如此，LTX是将原本大格式的马赛克色块破解成更小格式的色块，其原理是根据原有的马赛克色块基础上进行分解把100变成1甚至0.1，更加贴合原画质的色块大小<br />\n<br />\n当然了我不否认当色块分解到无法再分解时会有一小部分AI生成部分，但是整体呈现的效果绝对不是红果短剧那种输入关键词生成的千篇一律大差不差的男女主相貌可以比的，前者是根据色块模型分解辅助AI生成，后者是根据关键词从数据库直接提取模型生成，这两者还是有本质区别的，当前的技术能破解出最小尺寸的色块已经非常接近原画了，虽然不能一比一还原女优原本的户型但是也绝对不会把馒头B破解成蝴蝶B<br />\n<br />\n<br />\n接下来我以无码流出影片SDDE-625为例带各位看看LTX破解出的效果，左边是普通破解，中间是LTX破解，右边是无码流出原画（图片来源于其他论坛，如有侵权请联系删除）<br />\n<img src=\"assets/images/177834/2oFwVcG.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/1AD7vCY.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/kPxwJO4.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/1NR4bfn.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/SsxVLFS.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/UTBtaBj.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/dgJZFAq.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/migyjGo.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/yQiEWom.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/FA0Kh9Q.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/WHsSs6g.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/qBPPmK2.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/RMjFqh5.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/177834/9PiBi9y.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\">", "images": ["assets/images/177834/2oFwVcG.jpeg", "assets/images/177834/1AD7vCY.jpeg", "assets/images/177834/kPxwJO4.jpeg", "assets/images/177834/1NR4bfn.jpeg", "assets/images/177834/SsxVLFS.jpeg", "assets/images/177834/UTBtaBj.jpeg", "assets/images/177834/dgJZFAq.jpeg", "assets/images/177834/migyjGo.jpeg", "assets/images/177834/yQiEWom.jpeg", "assets/images/177834/FA0Kh9Q.jpeg", "assets/images/177834/WHsSs6g.jpeg", "assets/images/177834/qBPPmK2.jpeg", "assets/images/177834/RMjFqh5.jpeg", "assets/images/177834/9PiBi9y.jpeg"]}, "comments": [{"floor": 2, "author": "九尺巨根", "uid": "660173", "avatar": "", "date": "2026-10-24 00:53:14", "html": "以目前的技术，无码破解还是无法完全去掉打码的，只能无限接近吧。", "images": []}, {"floor": 3, "author": "xsmile", "uid": "401195", "avatar": "", "date": "2026-10-24 00:54:01", "html": "LTX的确强，缺点就是稍微有点慢，普通版基本上可以直接看，LTX就需要用时间换", "images": []}, {"floor": 4, "author": "Green2Grass", "uid": "617306", "avatar": "", "date": "2026-10-24 00:55:53", "html": "严重学习了！<br />\n高考过去那么多年了，头一次这么理性专心的看选项，而且还是屄屄，居然没有动一点私欲。", "images": []}, {"floor": 5, "author": "涂一乐", "uid": "561768", "avatar": "", "date": "2026-10-24 00:56:22", "html": "如果仔细看还是有差别，其实就是AI就是利用模型重绘了画面。但如果不那么苛刻的话，完全可以当流出无码片看了！", "images": []}, {"floor": 6, "author": "淦淦", "uid": "349328", "avatar": "", "date": "2026-10-24 01:02:07", "html": "技术进步很快也就一年时间就差不多完全还原了", "images": []}, {"floor": 7, "author": "wildlander", "uid": "486433", "avatar": "", "date": "2026-10-24 01:08:01", "html": "大佬威武！！！有了这个对比，结果很明白了。不较真的话，确实可以当无码看了", "images": []}, {"floor": 8, "author": "没脾气了", "uid": "601697", "avatar": "", "date": "2026-10-24 01:11:07", "html": "ltx也是风味破解，但是清晰度比lada好得多，虽然也是ai画出来的假b，但是画的还是挺真的<img src=\"static/image/smiley/javbus/1.png\" smilieid=\"86\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 9, "author": "没脾气了", "uid": "601697", "avatar": "", "date": "2026-10-24 01:12:15", "html": "不知道能不能用流出的片里的B的样子来针对性训练模型，来实现破解这个女优的片无限接近完美", "images": []}, {"floor": 10, "author": "chinayouyou", "uid": "674538", "avatar": "", "date": "2026-10-24 01:27:16", "html": "显卡要求40起&nbsp; &nbsp;看看后期能下发到30和20吧", "images": []}, {"floor": 11, "author": "jackwen", "uid": "565970", "avatar": "", "date": "2026-10-24 01:33:57", "html": "已经很接近了，看不见马赛克就行", "images": []}, {"floor": 12, "author": "korra", "uid": "362016", "avatar": "", "date": "2026-10-24 01:36:26", "html": "这去码也太高清，我都是用之前站内介绍的lada", "images": []}, {"floor": 13, "author": "t8888t", "uid": "597282", "avatar": "", "date": "2026-10-24 01:40:36", "html": "請問一下 除了解碼&nbsp;&nbsp;現在有什們最新的推薦可以讓舊片變高畫質的程式嗎?&nbsp; &nbsp;應該不單單只有解碼在進步而已吧&nbsp;&nbsp;用過一些轉畫質的軟體沒像現在解碼 這樣神跟日新月異", "images": []}, {"floor": 14, "author": "3222594268", "uid": "374527", "avatar": "", "date": "2026-10-24 01:40:56", "html": "对比无码流出，感觉LTX破解版的鲍鱼，更粉嫩美观", "images": []}, {"floor": 15, "author": "gza332686576", "uid": "631252", "avatar": "", "date": "2026-10-24 01:41:20", "html": "这就是破对了方向·破对了片子。有些去破些P都没什么镜头的···选择上就错了呀<img src=\"static/image/smiley/javbus/12.png\" smilieid=\"89\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 16, "author": "妇女之光", "uid": "126572", "avatar": "", "date": "2026-10-24 01:47:05", "html": "神了，已经非常接近流出片的水平", "images": []}, {"floor": 17, "author": "胸什么胸", "uid": "338043", "avatar": "", "date": "2026-10-24 02:02:49", "html": "楼主大大的实验很有建设性，这个方向是对的，认可，总比看着大一团马赛克好一点，或者比看javplayer破解的小团马赛克好。AI自己修复后看着不闹心，与实际差上一点又何妨", "images": []}, {"floor": 18, "author": "yman", "uid": "300936", "avatar": "", "date": "2026-10-24 02:07:30", "html": "新版效果是在动态比较明显，几乎没有空间扭曲", "images": []}, {"floor": 19, "author": "fa200200", "uid": "343707", "avatar": "", "date": "2026-10-24 02:41:29", "html": "真的已经无限接近了。这几天感觉又回到几年前流出的那段时间一样", "images": []}, {"floor": 20, "author": "lizheng900630", "uid": "354577", "avatar": "", "date": "2026-10-24 02:49:10", "html": "我记得流出的片子里&nbsp;&nbsp;有女优不带套的？", "images": []}, {"floor": 21, "author": "大波萌妹", "uid": "306213", "avatar": "", "date": "2026-10-24 03:23:20", "html": "大佬解一下abp 408<img src=\"static/image/smiley/javbus/1.png\" smilieid=\"86\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 22, "author": "嘴巴嘟嘟嘟", "uid": "285805", "avatar": "", "date": "2026-10-24 05:56:27", "html": "道高一尺魔高一丈", "images": []}, {"floor": 23, "author": "textws", "uid": "482536", "avatar": "", "date": "2026-10-24 06:38:52", "html": "仔细对比看了一下，现在的破解比以前清晰度高了很多，但是B型还是有细微差别", "images": []}, {"floor": 24, "author": "神奇的蓝星人", "uid": "463684", "avatar": "", "date": "2026-10-24 07:01:07", "html": "没有流出做对比，效果算是很不错了", "images": []}, {"floor": 25, "author": "windknight", "uid": "50526", "avatar": "", "date": "2026-10-24 07:09:57", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4966761&amp;ptid=177834\" target=\"_blank\"><font color=\"#999999\">九尺巨根 發表於 2026-10-24 00:53</font></a></font><br />\n以目前的技术，无码破解还是无法完全去掉打码的，只能无限接近吧。</blockquote></div><br />\n这不是目前技术的问题，这是底层原理决定了的。打码本质上可以理解为一种对原始内容的破坏性压缩，既然是破坏性压缩，在打码的同时原始信息就已经丢失了。所以从底层原理来说，无论是现在还是未来，都不可能出现直接在马赛克上还原原始视频内容的技术，无非就是补全的的更加真实而已。", "images": []}, {"floor": 26, "author": "windknight", "uid": "50526", "avatar": "", "date": "2026-10-24 07:13:32", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4966812&amp;ptid=177834\" target=\"_blank\"><font color=\"#999999\">t8888t 發表於 2026-10-24 01:40</font></a></font><br />\n請問一下 除了解碼&nbsp;&nbsp;現在有什們最新的推薦可以讓舊片變高畫質的程式嗎?&nbsp; &nbsp;應該不單單只有解碼在進步而已吧&nbsp;&nbsp;...</blockquote></div><br />\n使用Topaz Video 1.7.1之后的星光精准2.6模型，对于老片的画质修复有化腐朽为神奇的效果，论坛上tonytest一直在发星光精准2.6恢复的老片，你可以去看看效果。<br />\n星光精准2.6和这一次Jasna更换的LTX模型一样，都是替换使用了扩散模型来进行影片的修复，效果都是惊艳，问题也都一样，巨慢无比。<br />\n星光精准2.6比LTX还要慢，因为它是无差别的全片修复，耗时更长。", "images": []}, {"floor": 27, "author": "mfkqqq", "uid": "663525", "avatar": "", "date": "2026-10-24 07:33:09", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4966763&amp;ptid=177834\" target=\"_blank\"><font color=\"#999999\">xsmile 發表於 2026-10-24 00:54</font></a></font><br />\nLTX的确强，缺点就是稍微有点慢，普通版基本上可以直接看，LTX就需要用时间换 ...</blockquote></div><br />\n<font color=\"#454545\"><font style=\"font-size:12px\"> 不仅是时间问题。LTX属于美颜+脑补，而且脑补的细节更多是自作主张的，不是完全还原。</font></font><br />\n<font color=\"#454545\"><font style=\"font-size:12px\">特别细节上，LTX确明显不如普通破解，有些细节更是明显错误的（或者称为差别?）。</font></font><br />\n<font color=\"#454545\"><font style=\"font-size:12px\">细看几张流精图，在小阴唇-阴蒂结合的结构处，LTX与流出原画相比，有明显差别，倒是普通破解，清晰度差但是细节错误更少。</font></font>", "images": []}, {"floor": 28, "author": "mfkqqq", "uid": "663525", "avatar": "", "date": "2026-10-24 07:34:31", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4966930&amp;ptid=177834\" target=\"_blank\"><font color=\"#999999\">神奇的蓝星人 發表於 2026-10-24 07:01</font></a></font><br />\n没有流出做对比，效果算是很不错了</blockquote></div><br />\nLTX的出图，比流出原图，看来更漂亮。属于开美颜了。", "images": []}, {"floor": 29, "author": "VRTM", "uid": "287975", "avatar": "", "date": "2026-10-24 08:48:31", "html": "这破解是不是相当于先把马赛克抠图用ps修图然后再贴回去了，期待AI算法的加入看看效率会不会有革命性的突破", "images": []}, {"floor": 30, "author": "cnlin1024", "uid": "476092", "avatar": "", "date": "2026-10-24 08:51:05", "html": "第一张LTX还是不行，舌头都短半截了。", "images": []}, {"floor": 31, "author": "gary_ruan", "uid": "548692", "avatar": "", "date": "2026-10-24 08:57:15", "html": "如果说普通破解是印象派，那LTX就是写实派了，当然，还不能写真看<img src=\"static/image/smiley/javbus/12.png\" smilieid=\"89\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 32, "author": "fzjfzj1979", "uid": "641520", "avatar": "", "date": "2026-10-24 08:58:16", "html": "真是高人啊，社会进步就是站在技术前沿的人们创造的，谢谢", "images": []}, {"floor": 33, "author": "東京太熱", "uid": "333282", "avatar": "", "date": "2026-10-24 09:06:13", "html": "静态并不能说明什么，动态还是一坨", "images": []}, {"floor": 34, "author": "雷66", "uid": "681046", "avatar": "", "date": "2026-10-24 09:07:44", "html": "虽然现在科技进步,但是现在破解的片子,虽然鲍鱼更嫩.但是看多了感觉都很相似.没那种真实感.有点假", "images": []}, {"floor": 35, "author": "[email protected]", "uid": "90711", "avatar": "", "date": "2026-10-24 09:38:11", "html": "论坛为什么吸引人，就是因为有这种技术贴，学习受教了……", "images": []}, {"floor": 36, "author": "a8075788", "uid": "134600", "avatar": "", "date": "2026-10-24 09:43:05", "html": "已经是准无码状态了，不追求细节已经超强了<img src=\"static/image/smiley/javbus/23.png\" smilieid=\"101\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 37, "author": "x7x", "uid": "622611", "avatar": "", "date": "2026-10-24 09:46:47", "html": "感谢老哥拿流出的来对比。这么一看LTX仍有差距，有些镜头把b的形状皮肤都改了一点", "images": []}, {"floor": 38, "author": "卡鲁鸭", "uid": "656454", "avatar": "", "date": "2026-10-24 10:01:43", "html": "篠田优是真的嫩", "images": []}, {"floor": 39, "author": "black-sky", "uid": "429022", "avatar": "", "date": "2026-10-24 10:02:26", "html": "樓主厲害 這可以看出來 AI確實有幫忙美化了<img src=\"static/image/smiley/javbus/12.png\" smilieid=\"89\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 40, "author": "fyoyj123", "uid": "343927", "avatar": "", "date": "2026-10-24 10:03:35", "html": "目前的技术，不很仔细看，完全可以当作无码", "images": []}, {"floor": 41, "author": "逝水之痕", "uid": "504999", "avatar": "", "date": "2026-10-24 10:07:31", "html": "对于我来说，破解的不完整还不如不破解，时而模糊，时而清晰。比整片马赛克看起来还恶心", "images": []}, {"floor": 42, "author": "xixi663", "uid": "548250", "avatar": "", "date": "2026-10-24 10:25:33", "html": "当时看这部流出很喜欢", "images": []}, {"floor": 43, "author": "gopeedog", "uid": "599836", "avatar": "", "date": "2026-10-24 10:41:34", "html": "崩脸 白费的", "images": []}, {"floor": 44, "author": "iamaseed", "uid": "420042", "avatar": "", "date": "2026-10-24 10:43:32", "html": "太费时间了，跑了pred-211，1个半小时的片子，用最佳画质模式，跑了46个小时，5060ti的显卡，其实如果老片码不厚的情况下用10.0的版本就挺好了", "images": []}, {"floor": 45, "author": "WERGILX", "uid": "539387", "avatar": "", "date": "2026-10-24 10:59:16", "html": "感觉 [塚本]FAD 的高清无码有望实现", "images": []}, {"floor": 46, "author": "szq111", "uid": "399341", "avatar": "", "date": "2026-10-24 11:00:26", "html": "科技太强大了", "images": []}, {"floor": 47, "author": "站立者", "uid": "499203", "avatar": "", "date": "2026-10-24 11:01:59", "html": "LTX&nbsp;&nbsp;这个能给图片去码吗？", "images": []}, {"floor": 48, "author": "SlaveownerXXX", "uid": "692006", "avatar": "", "date": "2026-10-24 11:08:47", "html": "严肃学习，希望大佬能破解木下あずみ所有作品（可以优先破解MIGD-604 はじめての真性中出し 木下あずみ）", "images": []}, {"floor": 49, "author": "nayiyeshiwo", "uid": "491268", "avatar": "", "date": "2026-10-24 11:12:32", "html": "现在志的能接受，不是一团糊糊，变行", "images": []}, {"floor": 50, "author": "xiaoquanwang", "uid": "342706", "avatar": "", "date": "2026-10-24 11:16:50", "html": "牛逼啊，现在科技越来越厉害了，都可以以假乱真啊，有些甚至比原来的B还好看", "images": []}, {"floor": 51, "author": "更木剑八", "uid": "554633", "avatar": "", "date": "2026-10-24 12:17:46", "html": "今年的破解技术已经远超于前几年了，但是唯一的问题是影片播放时候的马赛克破解动态画面的稳定性<img src=\"static/image/smiley/javbus/16.png\" smilieid=\"93\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 52, "author": "zb465373526", "uid": "479450", "avatar": "", "date": "2026-10-24 12:51:27", "html": "我感觉我又有学习的冲动了，大学毕业后就再也没有过这种冲动。", "images": []}, {"floor": 53, "author": "lodestar", "uid": "387000", "avatar": "", "date": "2026-10-24 13:24:49", "html": "感觉破解现在已经非常牛掰啊", "images": []}, {"floor": 54, "author": "牛奶有毒", "uid": "314495", "avatar": "", "date": "2026-10-24 13:26:33", "html": "已经很接近了，科技佬可以啊", "images": []}, {"floor": 55, "author": "sora178463289", "uid": "304577", "avatar": "", "date": "2026-10-24 13:47:43", "html": "只要去掉那层格格，看上去自然像无码总得比有码好", "images": []}, {"floor": 56, "author": "a90120411", "uid": "174390", "avatar": "", "date": "2026-10-24 13:58:01", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4966761&amp;ptid=177834\" target=\"_blank\"><font color=\"#999999\">九尺巨根 發表於 2026-10-24 00:53</font></a></font><br />\n以目前的技术，无码破解还是无法完全去掉打码的，只能无限接近吧。</blockquote></div><br />\n马赛克的算法破坏了原始数据，不可逆的。理论上永远不可能做到100%还原。", "images": []}, {"floor": 57, "author": "星宮", "uid": "650220", "avatar": "", "date": "2026-10-24 14:02:39", "html": "感觉普通虽然模糊但是形状更接近，LTX细节比流出的还丰富,可以说是AI自我补充", "images": []}, {"floor": 58, "author": "yizhiji", "uid": "377256", "avatar": "", "date": "2026-10-24 14:07:50", "html": "哪天出个教程啊", "images": []}, {"floor": 59, "author": "涩君子", "uid": "698412", "avatar": "", "date": "2026-10-24 14:28:04", "html": "这个技术分析真是用了心了，建议给出下载路径", "images": []}, {"floor": 60, "author": "week526", "uid": "585547", "avatar": "", "date": "2026-10-24 14:39:06", "html": "LTX模型在细节上的确比普通破解在细节上要更好，要不是内存涨价我就自己组一个台式来捣鼓了。", "images": []}, {"floor": 61, "author": "猫宫", "uid": "287313", "avatar": "", "date": "2026-10-24 16:15:13", "html": "jasna-&nbsp;&nbsp;怎么样的&nbsp;&nbsp;我打开&nbsp;&nbsp;有些是红色的要安装什么吗", "images": []}, {"floor": 62, "author": "w0268", "uid": "275464", "avatar": "", "date": "2026-10-24 17:16:50", "html": "我想求教下，现在这个LTX模型是要付费的吗？我看有的群在卖这个，开源的话能不能提供下下载地址", "images": []}, {"floor": 63, "author": "wbbb1974", "uid": "136977", "avatar": "", "date": "2026-10-24 18:28:08", "html": "这样来说 费钱不说 还要花很长时间", "images": []}, {"floor": 64, "author": "漂泊", "uid": "278073", "avatar": "", "date": "2026-10-24 18:56:19", "html": "ltx是不是要收费？", "images": []}, {"floor": 65, "author": "haohaokan", "uid": "503291", "avatar": "", "date": "2026-10-24 19:00:47", "html": "AI太懂搞黄了", "images": []}, {"floor": 66, "author": "452328313", "uid": "325239", "avatar": "", "date": "2026-10-24 19:18:52", "html": "这破解效果确实牛，估计再过2 3年更牛逼了", "images": []}, {"floor": 67, "author": "452328313", "uid": "325239", "avatar": "", "date": "2026-10-24 19:20:06", "html": "现在的破解真牛，再过两三年估计跟流出版一样了", "images": []}, {"floor": 68, "author": "tzyokn", "uid": "567794", "avatar": "", "date": "2026-10-24 19:32:02", "html": "可我的硬件跟不上啊", "images": []}, {"floor": 69, "author": "lsp1007", "uid": "682648", "avatar": "", "date": "2026-10-24 20:00:35", "html": "有没有好用的参数推荐下啊，大佬", "images": []}, {"floor": 70, "author": "moonathrun", "uid": "153765", "avatar": "", "date": "2026-10-24 20:15:34", "html": "有么有大佬可以教我一下 怎么用LTX", "images": []}, {"floor": 71, "author": "ppo3527", "uid": "359274", "avatar": "", "date": "2026-10-24 20:56:33", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4967822&amp;ptid=177834\" target=\"_blank\"><font color=\"#999999\">moonathrun 發表於 2026-10-24 20:15</font></a></font><br />\n有么有大佬可以教我一下 怎么用LTX</blockquote></div><br />\n40系以上显卡可以考虑..这玩意要钱.买断制.140多.本地部署..去咸鱼", "images": []}, {"floor": 72, "author": "iqeq", "uid": "285309", "avatar": "", "date": "2026-10-24 22:20:24", "html": "利用无码流出来进行对比，真的是很专业的对比了，科技改变生活", "images": []}]};
